def require_env(*names: str) -> dict[str, str]:
    missing = [name for name in names if not os.environ.get(name, "").strip()]
    if missing:
        print("[ERREUR] Variables manquantes :")
        for name in missing:
            print(f"   - {name}")
        print("\nAjoutez-les dans .env.local ou exportez-les dans le terminal.")
        print("Voir les instructions en tête de export_storage.py.")
        sys.exit(1)
    return {name: os.environ[name].strip() for name in names}

