def download_with_retry(client: Client, bucket: str, path: str) -> bytes:
    last_error: Exception | None = None
    for attempt in range(1, MAX_RETRIES + 1):
        try:
            return client.storage.from_(bucket).download(path)
        except Exception as exc:  # noqa: BLE001 — API réseau hétérogène
