) -> tuple[StorageFile, Path, int]:
    destination = output_dir / storage_file.bucket / storage_file.path
    destination.parent.mkdir(parents=True, exist_ok=True)
    data = download_with_retry(client, storage_file.bucket, storage_file.path)
    destination.write_bytes(data)
    return storage_file, destination, len(data)

